export const heritageMatches = rows.map(([occurrenceId, season, competition, date, sortDate, rawHomeTeam, rawAwayTeam, rawOpponent, homeAway, scoreline, outcome, venue, scorerText, attendanceText]) => {
  const homeTeam = formatTeamName(rawHomeTeam)
  const awayTeam = formatTeamName(rawAwayTeam)
  const opponent = formatTeamName(rawOpponent)

  return {
    id: `heritage-${occurrenceId}`,
    title: `${homeTeam} ${scoreline} ${awayTeam}`,
    season, competition, date, sortDate, venue, homeTeam, awayTeam,
    result: `${outcome}: ${scoreline}`,
    opponent, homeAway, scoreline, outcome,
    scorers: scorerText ? scorerText.split(', ') : [],
    attendance: attendanceText || 'Not recorded',
    notes: `${competition} match from the ${season} season.`,
    timeline: [],
    tags: [season, competition, homeAway === 'H' ? 'Home' : homeAway === 'A' ? 'Away' : 'Neutral'],
    sourceLinks: [
      { label: 'Heritage Trust match record', url: `https://heritage.shamrockrovers.ie/index.php/Detail/occurrences/${occurrenceId}` },
      { label: `${season} season archive`, url: `https://heritage.shamrockrovers.ie/index.php/Domestic/Season?id=${encodeURIComponent(season)}` },
    ],
  }
})

const seasonMatches = heritageMatches.reduce((groups, match) => {
  const group = groups.get(match.season) ?? []
  group.push(match)
  groups.set(match.season, group)
  return groups
}, new Map())

export const heritageSeasons = seasonOrder.map((season) => {
  const matches = seasonMatches.get(season) ?? []
  const wins = matches.filter((match) => match.result.startsWith('Win')).length
  const draws = matches.filter((match) => match.result.startsWith('Draw')).length
  const defeats = matches.length - wins - draws
  const competitions = [...new Set(matches.map((match) => match.competition))]
  const startYear = Number.parseInt(season.slice(0, 4), 10)
  const decade = `${Math.floor(startYear / 10) * 10}s`

  return {
    id: `${season}-season`, title: `${season} season`, period: decade,
    manager: 'See individual match and club records', leagueFinish: 'Complete match record',
    cups: competitions.filter((competition) => competition !== 'League of Ireland').join(', ') || 'No cup fixtures recorded',
    europe: competitions.filter((competition) => /European|UEFA|Fairs Cup|Champions League|Conference League/.test(competition)).join(', ') || 'No European fixtures',
    topScorer: 'See season match scorers', stadium: 'See individual match venues',
    summary: `${matches.length} recorded matches: ${wins} wins, ${draws} draws, and ${defeats} defeats across ${competitions.length} competitions.`,
    highlights: [`${matches.length} matches recorded.`, `Record: W${wins} D${draws} L${defeats}.`, ...competitions],
    linkedMatchIds: matches.map((match) => match.id), tags: [season, decade, ...competitions],
    sourceLinks: [{ label: 'Official Heritage Trust season archive', url: `https://heritage.shamrockrovers.ie/index.php/Domestic/Season?id=${encodeURIComponent(season)}` }],
  }
})

export const heritageSeasonOptions = seasonOrder
